package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertEquals;

import java.net.URI;
import java.security.KeyPair;
import java.security.KeyStore.TrustedCertificateEntry;
import java.security.cert.CRL;
import java.security.cert.X509CRL;
import java.security.cert.X509Certificate;
import java.time.Instant;
import java.util.Collection;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import org.bouncycastle.asn1.x500.X500Name;
import org.eclipse.kura.core.testutil.pki.TestCA;
import org.eclipse.kura.core.testutil.pki.TestCA.CRLCreationOptions;
import org.eclipse.kura.core.testutil.pki.TestCA.CertificateCreationOptions;
import org.junit.After;
import org.junit.Test;

public class CrlIssuerBindingTest extends CrlKeystoreServiceTestBase {

    private static final String PARENT_ISSUER = "CN=Parent CA";
    private static final String OTHER_ISSUER = "CN=Other CA";
    private static final String CRL_PATH = "/intermediate.crl";
    private static final int DOWNLOADS_PER_CHECK = 3;
    private static final long DOWNLOAD_TIMEOUT_MS = 30_000;

    private final Map<String, Object> crlOptions = new HashMap<>();
    private CrlDistributionServer server;
    private TestCA parentCa;
    private X509Certificate intermediateCertificate;

    @After
    public void closeServer() throws Exception {
        if (this.server != null) {
            this.server.close();
        }
    }

    @Test
    public void crlOfAnotherIssuerIsRejectedWhenVerificationIsDisabled() throws Exception {
        givenCrlDistributionServer();
        givenIntermediateCertificateIssuedBy(PARENT_ISSUER);
        givenTrustedCertificate(this.intermediateCertificate);
        givenCrlPublishedBy(new TestCA(caOptions(OTHER_ISSUER)));
        givenCrlVerificationDisabled();
        givenKeystoreServiceWithCrlManagement(this.crlOptions);

        whenCrlIsDownloadedRepeatedly();

        thenServedCrlIssuersAre();
    }

    @Test
    public void crlOfTheCertificateIssuerIsAcceptedWhenVerificationIsDisabled() throws Exception {
        givenCrlDistributionServer();
        givenIntermediateCertificateIssuedBy(PARENT_ISSUER);
        givenTrustedCertificate(this.intermediateCertificate);
        givenCrlPublishedBy(this.parentCa);
        givenCrlVerificationDisabled();
        givenKeystoreServiceWithCrlManagement(this.crlOptions);

        whenCrlIsDownloadedRepeatedly();

        thenServedCrlIssuersAre(PARENT_ISSUER);
    }

    @Test
    public void crlOfTheExpectedIssuerReplacesACachedCrlOfAnotherIssuer() throws Exception {
        givenCrlDistributionServer();
        givenIntermediateCertificateIssuedBy(PARENT_ISSUER);
        givenCrlPublishedBy(new TestCA(caOptions(OTHER_ISSUER)));
        givenCrlVerificationDisabled();
        givenCrlUrlConfigured();
        givenKeystoreServiceWithCrlManagement(this.crlOptions);
        givenCrlCacheServing(OTHER_ISSUER);

        whenIntermediateCertificateIsTrusted();
        whenCrlIsPublishedBy(this.parentCa);
        whenCrlIsDownloadedRepeatedly();

        thenServedCrlIssuersAre(PARENT_ISSUER);
    }

    @Test
    public void crlSignedByTheKeyOfAnotherTrustedCertificateIsRejected() throws Exception {
        final KeyPair otherKeyPair = TestCA.generateKeyPair();

        givenCrlDistributionServer();
        givenTrustedCertificate(new TestCA(caOptions(PARENT_ISSUER)).getCertificate());
        givenTrustedCertificate(new TestCA(caOptions(OTHER_ISSUER), otherKeyPair).getCertificate());
        givenCrlPublishedBy(new TestCA(caOptions(PARENT_ISSUER), otherKeyPair));
        givenCrlVerificationEnabled();
        givenCrlUrlConfigured();
        givenKeystoreServiceWithCrlManagement(this.crlOptions);

        whenCrlIsDownloadedRepeatedly();

        thenServedCrlIssuersAre();
    }

    private void givenCrlDistributionServer() throws Exception {
        this.server = new CrlDistributionServer();
        this.crlOptions.put("crl.check.interval", 1L);
        this.crlOptions.put("crl.check.interval.time.unit", "SECONDS");
        this.crlOptions.put("crl.update.interval", 1L);
        this.crlOptions.put("crl.update.interval.time.unit", "SECONDS");
    }

    private void givenIntermediateCertificateIssuedBy(final String issuer) throws Exception {
        this.parentCa = new TestCA(caOptions(issuer));
        this.intermediateCertificate = this.parentCa.createAndSignCertificate(CertificateCreationOptions
                .builder(new X500Name("CN=Intermediate CA")).withCRLDownloadURI(new URI(this.server.url(CRL_PATH)))
                .build());
    }

    private void givenCrlPublishedBy(final TestCA ca) throws Exception {
        whenCrlIsPublishedBy(ca);
    }

    private void givenCrlVerificationDisabled() {
        this.crlOptions.put("verify.crl", false);
    }

    private void givenCrlVerificationEnabled() {
        this.crlOptions.put("verify.crl", true);
    }

    private void givenCrlUrlConfigured() {
        this.crlOptions.put("crl.urls", new String[] { this.server.url(CRL_PATH) });
    }

    private void givenCrlCacheServing(final String issuer) throws Exception {
        whenCrlIsDownloadedRepeatedly();
        thenServedCrlIssuersAre(issuer);
    }

    private void whenIntermediateCertificateIsTrusted() throws Exception {
        this.keystoreService.setEntry("intermediate", new TrustedCertificateEntry(this.intermediateCertificate));
    }

    private void whenCrlIsPublishedBy(final TestCA ca) throws Exception {
        this.server.publish(CRL_PATH, ca.generateCRL(CRLCreationOptions.builder()
                .withStartDate(Date.from(Instant.now().minusSeconds(60)))
                .withEndDate(Date.from(Instant.now().plusSeconds(3600))).build()));
    }

    private void whenCrlIsDownloadedRepeatedly() throws Exception {
        this.server.awaitDownloads(CRL_PATH, DOWNLOADS_PER_CHECK, DOWNLOAD_TIMEOUT_MS);
    }

    private void thenServedCrlIssuersAre(final String... expectedIssuers) throws Exception {
        final Set<String> expected = Set.of(expectedIssuers);

        assertEquals(expected, issuersOf(this.keystoreService.getCRLs()));
        assertEquals(expected, issuersOf(this.keystoreService.getCRLStore().getCRLs(null)));
    }

    private static CertificateCreationOptions caOptions(final String name) {
        return CertificateCreationOptions.builder(new X500Name(name)).build();
    }

    private static Set<String> issuersOf(final Collection<? extends CRL> crls) {
        return crls.stream().map(c -> ((X509CRL) c).getIssuerX500Principal().getName()).collect(Collectors.toSet());
    }
}
